// ============================================================================
// Recettes FRANÇAISES par familles de plats : une base (gratin, velouté,
// clafoutis, fricassée…) déclinée avec des ingrédients de saison ou de
// région. Chaque variante a ses propres ingrédients ET son étape de
// préparation propre (rien de copié). Les noms d'ingrédients sont ceux de la
// table `ingredients` ; les macros sont calculées à l'insertion.
// Insérées par scripts/ajouter-recettes-generees.ts --francaises.
// ============================================================================

import type { RecetteSaisie } from './recettes-proteinees';

type L = [string, number, string, boolean?];
type T = RecetteSaisie['type'];
/** Variante : `t` complète le titre, `i` ajoute des ingrédients, `x` est l'étape propre. */
interface V { t: string; i: L[]; x: string }

function fam(
  titre: (v: V) => string, type: T, prep: number, cuisson: number, difficulte: RecetteSaisie['difficulte'], conservation: number,
  ustensiles: string[], base: L[], vars: V[], etapes: (v: V) => string[], portions = 4,
): RecetteSaisie[] {
  return vars.map(v => ({
    titre: titre(v), type, cuisine: 'Française', prep, cuisson, difficulte, portions, conservation, ustensiles,
    ingredients: [...base, ...v.i], etapes: etapes(v),
  }));
}

